Script.Workflow:
module UbuntuButtonColors;
using presentation::*;
using presentation::controls::*;
namespace ubuntuskin
{
  struct ButtonColors
  {
    Border : Color;
    G1 : Color;
    G2 : Color;
    Text : Color;
    Bullet : Color;
  }

  class ButtonColorState
  {
    prop Border : Color = {} {}
    prop G1 : Color = {} {}
    prop G2 : Color = {} {}
    prop Text : Color = {} {}
    prop Bullet : Color = {} {}

    new() {}

    new(colors : ButtonColors)
    {
      Border = colors.Border;
      G1 = colors.G1;
      G2 = colors.G2;
      Text = colors.Text;
      Bullet = colors.Bullet;
    }
  }

  func CompleteColorAnimation(animation : IGuiAnimation^, completed : func():void) : IGuiAnimation^
  ${
    $PlayAndWait animation;
    completed();
  }

  func GetButtonColors(enabled : bool, state : ButtonState) : ButtonColors
  {
    return not enabled ? ubuntuColors.ButtonDisabled :
      state == ButtonState::Pressed ? ubuntuColors.ButtonPressed :
      state == ButtonState::Active ? ubuntuColors.ButtonHovered : ubuntuColors.ButtonNormal;
  }

  func GetCheckedColors(enabled : bool, state : ButtonState, selected : bool) : ButtonColors
  {
    var colors = not enabled ? ubuntuColors.CheckedDisabled :
      state == ButtonState::Pressed ? ubuntuColors.CheckedPressed :
      state == ButtonState::Active ? ubuntuColors.CheckedHovered : ubuntuColors.CheckedNormal;
    var checkedFace = enabled ? (state == ButtonState::Pressed ? ubuntuColors.ControlAccentPressed : ubuntuColors.ControlAccent) : ubuntuColors.DisabledInk;
    return {
      Border: selected ? checkedFace : colors.Border;
      G1: selected ? checkedFace : colors.G1;
      G2: selected ? checkedFace : colors.G2;
      Text: colors.Text;
      Bullet: selected ? colors.Bullet : {r:colors.Bullet.r; g:colors.Bullet.g; b:colors.Bullet.b; a:ubuntuColors.Clear.a;};
    };
  }

  func GetScrollButtonColors(enabled : bool, state : ButtonState, arrow : bool) : ButtonColors
  {
    if (arrow)
    {
      return not enabled ? ubuntuColors.CommandDisabled :
        state == ButtonState::Pressed ? ubuntuColors.CommandPressed :
        state == ButtonState::Active ? ubuntuColors.CommandHovered : ubuntuColors.CommandNormal;
    }
    return not enabled ? ubuntuColors.ScrollHandleDisabled :
      state == ButtonState::Pressed ? ubuntuColors.ScrollHandlePressed :
      state == ButtonState::Active ? ubuntuColors.ScrollHandleActive : ubuntuColors.ScrollHandleNormal;
  }
}

Instance.ref.Members:
var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(ubuntuColors.ButtonNormal));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetButtonColors(self.VisuallyEnabled, self.State)), cast UInt64 150), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 150), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 150), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}
